  function spawnRock(){const r=12+Math.random()*18+Math.min(elapsed*.12,12);rocks.push({x:r+Math.random()*(W-r*2),y:-r,r,vx:(Math.random()-.5)*35,vy:75+Math.random()*65+Math.min(elapsed*2,100),rot:Math.random()*6,spin:(Math.random()-.5)*2,hp:r>29?2:1,seed:Math.random()*100})}
  function fire(){shots.push({x:ship.x,y:ship.y-16,vy:-490});beep(540,.035)}
