   spawnTimer-=dt;if(spawnTimer<=0){spawnRock();spawnTimer=Math.max(.27,.85-elapsed*.008)+Math.random()*.34}
-  shotTimer-=dt;if((keys.fire||true)&&shotTimer<=0){fire();shotTimer=.24}
