   for(let i=shots.length-1;i>=0;i--){const s=shots[i];s.y+=s.vy*dt;if(s.y<-10){shots.splice(i,1);continue}for(let j=rocks.length-1;j>=0;j--){const a=rocks[j];if(Math.hypot(a.x-s.x,a.y-s.y)<a.r){shots.splice(i,1);a.hp--;burst(s.x,s.y,'#69f6ff',5);if(a.hp<=0){burst(a.x,a.y,'#ffb666',12);if(Math.random()<.14)gems.push({x:a.x,y:a.y,vy:115,phase:Math.random()*6});rocks.splice(j,1);setScore(score+100);beep(280,.07)}break}}}
   for(let i=gems.length-1;i>=0;i--){const g=gems[i];g.y+=g.vy*dt;g.phase+=dt*5;if(Math.hypot(g.x-ship.x,g.y-ship.y)<ship.r+10){gems.splice(i,1);setScore(score+250);burst(g.x,g.y,'#ffda78',12);beep(850,.14)}else if(g.y>H+20)gems.splice(i,1)}
   for(let i=sparks.length-1;i>=0;i--){const p=sparks[i];p.x+=p.vx*dt;p.y+=p.vy*dt;p.vx*=.985;p.vy*=.985;p.life-=dt;if(p.life<=0)sparks.splice(i,1)}

