  window.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight',' ','a','A','d','D'].includes(e.key))e.preventDefault();if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A')keys.left=true;if(e.key==='ArrowRight'||e.key==='d'||e.key==='D')keys.right=true;if(e.key===' ')keys.fire=true;if(e.key==='Escape'&&state==='playing'){state='paused';document.querySelector('#eyebrow').textContent='PAUSED';document.querySelector('#headline').innerHTML='TAKE A<br>BREATHER';document.querySelector('#message').textContent='The starfield can wait. Ready to jump back in?';playBtn.textContent='RESUME RUN';overlay.classList.remove('hidden');playBtn.onclick=()=>{state='playing';overlay.classList.add('hidden');last=performance.now();playBtn.onclick=null}}});
  window.addEventListener('keyup',e=>{if(e.key==='ArrowLeft'||e.key==='a'||e.key==='A')keys.left=false;if(e.key==='ArrowRight'||e.key==='d'||e.key==='D')keys.right=false;if(e.key===' ')keys.fire=false});
  document.querySelectorAll('.control').forEach(b=>{const k=b.dataset.key;const down=e=>{e.preventDefault();keys[k]=true;b.classList.add('active');try{b.setPointerCapture(e.pointerId)}catch{}};const up=e=>{e.preventDefault();keys[k]=false;b.classList.remove('active')};b.addEventListener('pointerdown',down);b.addEventListener('pointerup',up);b.addEventListener('pointercancel',up);b.addEventListener('lostpointercapture',up)});
  document.querySelector('#sound').addEventListener('click',e=>{soundOn=!soundOn;e.currentTarget.textContent=soundOn?'♪ SOUND ON':'♪ SOUND OFF'});

